import 'package:flutter/material.dart'; import 'azkar_page.dart'; import 'khatma_page.dart'; import 'sleep_azkar_page.dart'; import 'home_page.dart'; import 'settings_page.dart'; import 'privacy_policy_page.dart'; import 'licenses_page.dart'; import 'about_page.dart'; import 'favorite_ayahs_page.dart'; import 'audio_downloads_page.dart';
class MorePage extends StatelessWidget{const MorePage({super.key});@override Widget build(BuildContext context)=>ListView(padding:const EdgeInsets.all(16),children:[_item(context,Icons.checklist,Colors.teal,'وردي اليومي',const HomePage()),_item(context,Icons.favorite,Colors.red,'الأذكار',const AzkarPage()),_item(context,Icons.star,Colors.amber,'مفضلة الآيات',const FavoriteAyahsPage()),_item(context,Icons.download_for_offline,Colors.blue,'تحميل الصوت',const AudioDownloadsPage()),_item(context,Icons.task_alt,Colors.orange,'الختمة',const KhatmaPage()),_item(context,Icons.nights_stay,Colors.indigo,'أذكار النوم',const SleepAzkarPage()),_item(context,Icons.privacy_tip,Colors.green,'سياسة الخصوصية',const PrivacyPolicyPage()),_item(context,Icons.gavel,Colors.blue,'المصادر والتراخيص',const LicensesPage()),_item(context,Icons.settings,Colors.green,'الإعدادات',const SettingsPage()),_item(context,Icons.info_outline,Colors.grey,'حول التطبيق',const AboutPage())]);Widget _item(BuildContext c,IconData icon,Color color,String title,Widget page)=>Card(child:ListTile(leading:Icon(icon,color:color),title:Text(title),trailing:const Icon(Icons.arrow_forward_ios),onTap:()=>Navigator.push(c,MaterialPageRoute(builder:(_)=>Directionality(textDirection:TextDirection.rtl,child:Scaffold(appBar:AppBar(title:Text(title),centerTitle:true),body:page))))));}
